options(stringsAsFactors=FALSE)
suppressPackageStartupMessages({library(survival);library(ggplot2);library(patchwork)})
script<-normalizePath(sub('^--file=','',grep('^--file=',commandArgs(),value=TRUE)[1]));out<-dirname(dirname(script));base<-dirname(dirname(out))
d<-read.csv(file.path(out,'tables/patient_data_PRE73.csv'));d$group<-factor(d$group,levels=c('Low','High'))
stopifnot(nrow(d)==73,sum(d$event)==29,all(as.character(d$group)==ifelse(d$Balance>median(d$Balance),'High','Low')))
write.csv(data.frame(median=median(d$Balance),rule='High > median; Low <= median',n_Low=sum(d$group=='Low'),n_High=sum(d$group=='High')),file.path(out,'tables/threshold.csv'),row.names=FALSE)
lr<-survdiff(Surv(OS_days,event)~group,d,rho=0);P<-pchisq(lr$chisq,1,lower.tail=FALSE)
st<-data.frame(n=73,deaths=29,n_Low=37,n_High=36,events_Low=unname(lr$obs[1]),events_High=unname(lr$obs[2]),expected_Low=unname(lr$exp[1]),expected_High=unname(lr$exp[2]),chi_square=lr$chisq,df=1,P_logrank_nominal=P)
prior<-read.csv(file.path(base,'results/Fig5_PRE73_Delta_HighLow_OS_26.09.20/tables/primary_logrank_results.csv'))
stopifnot(abs(P-prior$P_logrank_nominal)<1e-12,abs(lr$exp[1]-prior$expected_Low)<1e-12)
write.csv(st,file.path(out,'tables/primary_logrank_results.csv'),row.names=FALSE)
sf<-survfit(Surv(OS_days,event)~group,d,conf.type='log-log');s<-summary(sf,censored=TRUE)
k<-data.frame(group=sub('group=','',s$strata),time=s$time,survival=s$surv,lower95=s$lower,upper95=s$upper,n_risk=s$n.risk,n_event=s$n.event,n_censor=s$n.censor)
k<-rbind(data.frame(group=c('Low','High'),time=0,survival=1,lower95=1,upper95=1,n_risk=c(37,36),n_event=0,n_censor=0),k);k<-k[order(k$group,k$time),]
tab<-summary(sf)$table;gs<-data.frame(group=c('Low','High'),n=c(37,36),events=unname(lr$obs),median_OS_days=tab[,'median'],median_lower95=tab[,'0.95LCL'],median_upper95=tab[,'0.95UCL'])
rt<-expand.grid(time=seq(0,1600,400),group=c('Low','High'));rt$n_risk<-mapply(function(t,g)sum(d$OS_days[d$group==g]>=t),rt$time,rt$group)
fit<-coxph(Surv(OS_days,event)~group,d,ties='efron',x=TRUE);cs<-summary(fit);co<-cs$coefficients;ci<-cs$conf.int
cx<-data.frame(term='Balance High versus Low',HR=ci[1,'exp(coef)'],CI_low=ci[1,'lower .95'],CI_high=ci[1,'upper .95'],coef=co[1,'coef'],se=co[1,'se(coef)'],Wald_P=co[1,'Pr(>|z|)'],LRT_P=unname(cs$logtest['pvalue']),score_test_P=unname(cs$sctest['pvalue']),ties='efron')
oldcx<-read.csv(file.path(base,'results/Fig5_PRE73_Delta_HighLow_OS_26.09.20/tables/Cox_HR.csv'));stopifnot(abs(cx$HR-oldcx$HR)<1e-10)
ph<-cox.zph(fit);phout<-data.frame(term=rownames(ph$table),ph$table,row.names=NULL)
for(nm in c('KM_steps','group_summary','risk_table','Cox_HR','PH_diagnostics'))write.csv(switch(nm,KM_steps=k,group_summary=gs,risk_table=rt,Cox_HR=cx,PH_diagnostics=phout),file.path(out,'tables',paste0(nm,'.csv')),row.names=FALSE,na='NA')
prism<-data.frame(Time_days=d$OS_days,Balance_Low=ifelse(d$group=='Low',d$event,NA),Balance_High=ifelse(d$group=='High',d$event,NA));prism<-prism[order(prism$Time_days),];write.csv(prism,file.path(out,'tables/PRISM_OS_Balance.csv'),row.names=FALSE,na='')
COL<-c(High='#E41A1C',Low='#2455D6');INK<-'#111111';k$group<-factor(k$group,levels=c('High','Low'));rt$group<-factor(rt$group,levels=c('Low','High'))
medpos<-data.frame(group=c('High','Low'),x=c(1020,1090),y=c(87,23),label=ifelse(is.na(gs$median_OS_days[match(c('High','Low'),gs$group)]),'Median OS:\nnot reached',sprintf('Median OS:\n%d days',as.integer(gs$median_OS_days[match(c('High','Low'),gs$group)]))))
scx<-function()scale_x_continuous(breaks=seq(0,1600,400),limits=c(-28,1660),expand=c(0,0))
top<-ggplot(k,aes(time,survival*100,colour=group))+geom_step(linewidth=1.15,direction='hv')+geom_point(data=k[k$n_censor>0,],shape=3,size=2.65,stroke=.85)+geom_text(data=medpos,aes(x=x,y=y,label=label,colour=group),inherit.aes=FALSE,hjust=0,size=4.6,lineheight=.95,show.legend=FALSE)+annotate('text',x=65,y=6,label=sprintf('Log-rank P = %.3f',P),hjust=0,size=5,colour=INK)+scale_colour_manual(values=COL,breaks=c('High','Low'),labels=c('Balance High (n = 36)','Balance Low (n = 37)'))+scx()+scale_y_continuous(limits=c(-1.5,102),breaks=seq(0,100,25),expand=c(0,0))+labs(title='Sarcosine metabolic balance',subtitle='Degradation - Production\nMelanoma, pretreatment | 73 patients; 29 deaths',x='Time (days)',y='Overall survival (%)',colour=NULL)+theme_classic(base_size=16,base_family='Arial')+theme(text=element_text(colour=INK),axis.text=element_text(size=15,colour=INK),axis.title=element_text(size=17),axis.title.x=element_text(margin=margin(t=8)),axis.title.y=element_text(margin=margin(r=8)),axis.line=element_line(linewidth=.7),axis.ticks=element_line(linewidth=.7),plot.title=element_text(size=22,face='bold',margin=margin(b=5)),plot.subtitle=element_text(size=12.5,colour='#444444',lineheight=1.25,margin=margin(b=8)),legend.position='top',legend.justification='left',legend.text=element_text(size=13),legend.key.width=grid::unit(23,'pt'),plot.margin=margin(8,12,3,12))+guides(colour=guide_legend(ncol=1))
bottom<-ggplot(rt,aes(time,group,label=n_risk,colour=group))+geom_text(size=5.2)+scale_colour_manual(values=COL,guide='none')+scx()+labs(title='Number at risk',x=NULL,y=NULL)+theme_void(base_family='Arial')+theme(plot.title=element_text(size=14,colour=INK,margin=margin(b=7)),axis.text.y=element_text(size=14,colour=INK,margin=margin(r=10)),plot.margin=margin(3,12,6,12))
fig<-top/bottom+plot_layout(heights=c(4.2,.72))+plot_annotation(caption='Pooled PRE73 median split. + indicates censoring.\nExploratory comparison; nominal log-rank P.',theme=theme(plot.caption=element_text(size=10,hjust=0,colour='#444444',lineheight=1.2),plot.margin=margin(6,6,6,6)))
ggsave(file.path(out,'figures/Balance_HighLow_OS.png'),fig,width=7,height=7.3,dpi=450,bg='white',device=ragg::agg_png)
ggsave(file.path(out,'figures/Balance_HighLow_OS.pdf'),fig,width=7,height=7.3,bg='white',device=cairo_pdf)
write.csv(k,file.path(out,'qa/plotted_KM.csv'),row.names=FALSE);write.csv(rt,file.path(out,'qa/plotted_risk.csv'),row.names=FALSE)
capture.output(sessionInfo(),file=file.path(out,'qa/sessionInfo.txt'));print(st);print(gs);print(cx);print(phout)
